    lo = 0.0
    hi = 1.0
    # Expand hi until P(hi) > 0
    for _ in range(60):
        if P(hi) > 0:
            break
        hi *= 2.0
    # Bisection to bracket
    for _ in range(80):
        mid = 0.5*(lo+hi)
        val = P(mid)
        if val == 0:
            lo = hi = mid
            break
        if val > 0:
            hi = mid
        else:
            lo = mid
    x = 0.5*(lo+hi)
    # Newton refinement
    for _ in range(20):
        dp = dP(x)
        if abs(dp) < 1e-12:
            break
        x_new = x - P(x)/dp
        if x_new <= 0:
            break
        if abs(x_new - x) < 1e-12:
            x = x_new
            break
        x = x_new
    return x

