        for j in range(i+1, len(moduli)):
            if gcd(moduli[i], moduli[j]) != 1:
                return (False, None)
    # Enumerate satisfying classes via CRT
    classes = []  # representatives in [0, total_modulus-1]
    # Start with first modulus' residues
    m0, R0 = residues_list[0]
    for r0 in R0:
        classes.append((r0 % m0, m0))
    # Iteratively merge
    for idx in range(1, len(residues_list)):
        m_i, R_i = residues_list[idx]
        new_classes = []
        for (a, mod_a) in classes:
            for b_res in R_i:
                x, new_mod = crt_pair(a, mod_a, b_res % m_i, m_i)
                if x is None:
                    return (False, None)
                new_classes.append((x, new_mod))
        classes = new_classes
    # Extract representatives modulo total_modulus
    S = sorted([x for (x, mm) in classes])
    if len(S) == 0:
        return (False, None)
    # Count in 1..M by periodicity mod total_modulus
    full_blocks = M // total_modulus
    rem = M % total_modulus
    base = full_blocks * len(S)
    # Representatives are in 0..total_modulus-1, convert to 1..total_modulus for counting
    count_partial = 0
    for v in S:
        rep = v if v != 0 else total_modulus
        # We count numbers m with 1 <= m <= rem
        if rep != 0 and rep <= rem:
            count_partial += 1
    total_qualified = base + count_partial
    answer = f"### The final answer is: \\boxed{{{total_qualified}}}"
    return (True, answer)
